arguments.command:
curl -s -X POST https://api.linear.app/graphql -H 'Authorization: <TOKEN>' -H 'Content-Type: application/json' -d '{"query":"{ __schema { queryType { fields { name args { name type { name kind ofType { name } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['queryType']['fields']:
    if f['name'] in ('comments','issue','issues'):
        print(f['name'])
        for a in f['args']:
            t=a['type']
            print('  ',a['name'],t['kind'],t.get('name') or (t['ofType'] and t['ofType']['name']))
"

